INSERT INTO public.trail_spot (
    mountain_id, dataset_id, src_spot_id, src_old_spot_id, src_class_cd, src_class_nm,
    detail_txt, etc_txt, geom, src_geom, verify_status_cd
)
SELECT
    current_setting('orda.seed.mountain_id')::integer, dataset.dataset_id, seed.src_spot_id, seed.src_old_spot_id,
    seed.src_class_cd, seed.src_class_nm, seed.detail_txt, seed.etc_txt, seed.geom, seed.geom,
    'UNVERIFIED'
FROM tmp_acha_spot_seed AS seed
JOIN public.source_dataset AS dataset
  ON dataset.dataset_nm = seed.dataset_nm
 AND dataset.data_ver IN ('sha256:ebf41ab1754a34e8')
ON CONFLICT (dataset_id, src_spot_id) DO NOTHING;

DO $$
DECLARE
    raw_count bigint;
    spot_count bigint;
BEGIN
    SELECT COUNT(*) INTO raw_count FROM public.raw_trail WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;
    SELECT COUNT(*) INTO spot_count FROM public.trail_spot WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;
    IF raw_count <> 246 THEN RAISE EXCEPTION '아차산 raw_trail은 246건이어야 합니다. 실제: %', raw_count; END IF;
    IF spot_count <> 676 THEN RAISE EXCEPTION '아차산 trail_spot은 676건이어야 합니다. 실제: %', spot_count; END IF;
END
$$;

-- 활성 raw trail에서 아차산 네트워크를 생성한다.
-- 아차산 등산로 네트워크 최초 생성
-- 대상 산: mountain_id = current_setting('orda.seed.mountain_id')::integer
-- 대상 좌표계: EPSG:5179
--
-- 생성 원칙:
--   * 이 파일에서 산과 원천 등산로를 적재한 다음 한 번 실행한다.
--   * 기존 trail_edge 또는 trail_node가 있으면 참조 데이터와 장소 연결을 보호하기 위해 중단한다.
--   * use_yn = 'Y'인 모든 raw_trail을 대상으로 한다.
--   * raw trail을 모든 교차점에서 분할하고 분할 구간의 끝점을 노드 후보로 사용한다.
--   * 서로 1m 이내인 분할 구간 끝점을 하나의 노드로 묶는다.
--   * 분할 구간마다 trail_edge를 생성하고 원본 raw_trail_id를 보존한다.
--   * 원천 데이터만으로 진행 방향을 확정할 수 없으므로 방향·시간·고도 값은
--     UNKNOWN 또는 NULL로 두고 원천 값은 raw_trail에 보존한다.
--   * length_m은 EPSG:5179 geometry의 실제 길이로 계산한다.
--   * edge_cnt와 component_no는 생성된 전체 네트워크를 기준으로 다시 계산한다.


-- 같은 산에 대한 네트워크 생성이 동시에 실행되지 않도록 트랜잭션 잠금을 건다.
SELECT pg_advisory_xact_lock(5179, current_setting('orda.seed.mountain_id')::integer);

-- 이 파일은 신규 빈 DB의 최초 네트워크 생성 전용이다.
-- 기존 네트워크를 삭제하면 routing_run, spot_edge_match의 FK 참조가 깨질 수 있고,
-- FK가 없는 route_candidate.edge_seq와 기존 trail_node.place_id도 유효하지 않게 된다.
-- 네트워크가 이미 있으면 어떤 데이터도 삭제하지 않고 전체 작업을 중단한다.
DO $$
DECLARE
    existing_edge_count bigint;
    existing_node_count bigint;
BEGIN
    SELECT COUNT(*)
    INTO existing_edge_count
    FROM public.trail_edge
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;

    SELECT COUNT(*)
    INTO existing_node_count
    FROM public.trail_node
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;

    IF existing_edge_count > 0 OR existing_node_count > 0 THEN
        RAISE EXCEPTION
            '아차산 네트워크가 이미 존재합니다(edge %, node %). 기존 참조와 place_id 연결을 보호하기 위해 최초 생성 시드를 중단합니다.',
            existing_edge_count,
            existing_node_count;
    END IF;
END
$$;

-- 활성 raw trail이 없거나 빈 geometry가 있으면 전체 작업을 중단한다.
DO $$
DECLARE
    active_raw_trail_count bigint;
BEGIN
    SELECT COUNT(*)
    INTO active_raw_trail_count
    FROM public.raw_trail
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
      AND use_yn = 'Y';

    IF active_raw_trail_count = 0 THEN
        RAISE EXCEPTION '현재 산의 활성 raw_trail이 없습니다.';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.raw_trail
        WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
          AND use_yn = 'Y'
          AND ST_IsEmpty(geom)
    ) THEN
        RAISE EXCEPTION '현재 산의 활성 raw_trail에 빈 geometry가 있습니다.';
    END IF;
END
$$;

-- 전체 활성 raw trail을 이번 네트워크 생성 대상으로 고정한다.
CREATE TEMP TABLE tmp_acha_raw_trail
ON COMMIT DROP
AS
SELECT
    rt.raw_trail_id,
    rt.mountain_id,
    rt.geom
FROM public.raw_trail AS rt
WHERE rt.mountain_id = current_setting('orda.seed.mountain_id')::integer
  AND rt.use_yn = 'Y';

CREATE UNIQUE INDEX tmp_acha_raw_trail_pk
    ON tmp_acha_raw_trail (raw_trail_id);

-- 전체 선형을 교차점에서 noding한 뒤 모든 교차점 후보를 추출한다.
-- 한 raw trail의 끝점이 다른 raw trail의 내부에 닿는 경우도 이 단계에서 노드 후보가 된다.
CREATE TEMP TABLE tmp_acha_noded_line
ON COMMIT DROP
AS
WITH linework AS (
    SELECT ST_UnaryUnion(ST_Collect(geom)) AS geom
    FROM tmp_acha_raw_trail
)
SELECT
    ROW_NUMBER() OVER (ORDER BY ST_AsEWKB(dumped.geom))::bigint AS noded_line_id,
    dumped.geom::geometry(LineString, 5179) AS geom
FROM linework
CROSS JOIN LATERAL ST_Dump(ST_CollectionExtract(linework.geom, 2)) AS dumped;

CREATE UNIQUE INDEX tmp_acha_noded_line_pk
    ON tmp_acha_noded_line (noded_line_id);

CREATE INDEX tmp_acha_noded_line_geom_gix
    ON tmp_acha_noded_line
    USING gist (geom);

CREATE TEMP TABLE tmp_acha_noding_point
ON COMMIT DROP
AS
SELECT ST_StartPoint(geom)::geometry(Point, 5179) AS geom
FROM tmp_acha_noded_line

UNION

SELECT ST_EndPoint(geom)::geometry(Point, 5179) AS geom
FROM tmp_acha_noded_line;

CREATE UNIQUE INDEX tmp_acha_noding_point_pk
    ON tmp_acha_noding_point (ST_AsEWKB(geom));

CREATE INDEX tmp_acha_noding_point_geom_gix
    ON tmp_acha_noding_point
    USING gist (geom);

-- 각 raw trail을 자신 위의 모든 noding point에서 분할한다.
-- ST_ClosestPoint로 1mm 이내의 수치 오차를 선 위에 투영하고,
-- ST_Snap으로 교차를 보장한 뒤 ST_Split에 전달한다.
CREATE TEMP TABLE tmp_acha_segment
ON COMMIT DROP
AS
WITH split_parts AS (
    SELECT
        raw.raw_trail_id,
        raw.mountain_id,
        raw.geom AS raw_geom,
        dumped.geom::geometry(LineString, 5179) AS geom
    FROM tmp_acha_raw_trail AS raw
    LEFT JOIN LATERAL (
        SELECT ST_Collect(projected.geom) AS geom
        FROM (
            SELECT ST_ClosestPoint(raw.geom, point.geom)::geometry(Point, 5179) AS geom
            FROM tmp_acha_noding_point AS point
            WHERE ST_DWithin(raw.geom, point.geom, 0.001)
            GROUP BY ST_ClosestPoint(raw.geom, point.geom)
        ) AS projected
    ) AS blade
      ON TRUE
    CROSS JOIN LATERAL ST_Dump(
        CASE
            WHEN blade.geom IS NULL THEN raw.geom
            ELSE ST_Split(
                ST_Snap(raw.geom, blade.geom, 0.001),
                blade.geom
            )
        END
    ) AS dumped
    WHERE GeometryType(dumped.geom) = 'LINESTRING'
      AND ST_Length(dumped.geom) > 0.001
),
oriented_parts AS (
    SELECT
        raw_trail_id,
        mountain_id,
        CASE
            WHEN ST_LineLocatePoint(raw_geom, ST_StartPoint(geom))
               <= ST_LineLocatePoint(raw_geom, ST_EndPoint(geom))
                THEN geom
            ELSE ST_Reverse(geom)::geometry(LineString, 5179)
        END AS geom,
        LEAST(
            ST_LineLocatePoint(raw_geom, ST_StartPoint(geom)),
            ST_LineLocatePoint(raw_geom, ST_EndPoint(geom))
        ) AS start_fraction
    FROM split_parts
)
SELECT
    ROW_NUMBER() OVER (
        ORDER BY raw_trail_id, start_fraction, ST_AsEWKB(geom)
    )::bigint AS segment_id,
    raw_trail_id,
    mountain_id,
    geom
FROM oriented_parts;

CREATE UNIQUE INDEX tmp_acha_segment_pk
    ON tmp_acha_segment (segment_id);

CREATE INDEX tmp_acha_segment_raw_trail_idx
    ON tmp_acha_segment (raw_trail_id);

CREATE INDEX tmp_acha_segment_geom_gix
    ON tmp_acha_segment
    USING gist (geom);

-- 분할 과정에서 raw trail이 누락되거나 교차점이 분할되지 않았으면 중단한다.
DO $$
DECLARE
    invalid_segment_source_count bigint;
    unsplit_noding_point_count bigint;
BEGIN
    WITH segment_summary AS (
        SELECT
            raw_trail_id,
            COUNT(*) AS segment_count,
            SUM(ST_Length(geom)) AS total_length_m
        FROM tmp_acha_segment
        GROUP BY raw_trail_id
    )
    SELECT COUNT(*)
    INTO invalid_segment_source_count
    FROM tmp_acha_raw_trail AS raw
    LEFT JOIN segment_summary AS summary
      ON summary.raw_trail_id = raw.raw_trail_id
    WHERE summary.segment_count IS NULL
       OR ABS(ST_Length(raw.geom) - summary.total_length_m) > 0.01;

    IF invalid_segment_source_count > 0 THEN
        RAISE EXCEPTION
            '분할 구간이 누락됐거나 원본 길이와 일치하지 않는 raw_trail이 %건 있습니다.',
            invalid_segment_source_count;
    END IF;

    SELECT COUNT(*)
    INTO unsplit_noding_point_count
    FROM tmp_acha_raw_trail AS raw
    JOIN tmp_acha_noding_point AS point
      ON ST_DWithin(raw.geom, point.geom, 0.001)
    CROSS JOIN LATERAL (
        SELECT ST_ClosestPoint(raw.geom, point.geom)::geometry(Point, 5179) AS geom
    ) AS projected
    WHERE ST_LineLocatePoint(raw.geom, projected.geom) > 0.000000001
      AND ST_LineLocatePoint(raw.geom, projected.geom) < 0.999999999
      AND NOT EXISTS (
          SELECT 1
          FROM tmp_acha_segment AS segment
          WHERE segment.raw_trail_id = raw.raw_trail_id
            AND (
                ST_DWithin(ST_StartPoint(segment.geom), projected.geom, 0.001)
                OR ST_DWithin(ST_EndPoint(segment.geom), projected.geom, 0.001)
            )
      );

    IF unsplit_noding_point_count > 0 THEN
        RAISE EXCEPTION
            'raw_trail 내부의 noding point 중 분할 구간 끝점으로 반영되지 않은 지점이 %건 있습니다.',
            unsplit_noding_point_count;
    END IF;
END
$$;

-- 분할된 각 segment에서 시작점과 끝점을 추출한다.
CREATE TEMP TABLE tmp_acha_endpoint
ON COMMIT DROP
AS
SELECT
    ROW_NUMBER() OVER (
        ORDER BY endpoint.segment_id, endpoint.endpoint_type
    )::bigint AS endpoint_id,
    endpoint.segment_id,
    endpoint.raw_trail_id,
    endpoint.endpoint_type,
    endpoint.geom
FROM (
    SELECT
        segment_id,
        raw_trail_id,
        'SOURCE'::varchar AS endpoint_type,
        ST_StartPoint(geom)::geometry(Point, 5179) AS geom
    FROM tmp_acha_segment

    UNION ALL

    SELECT
        segment_id,
        raw_trail_id,
        'TARGET'::varchar AS endpoint_type,
        ST_EndPoint(geom)::geometry(Point, 5179) AS geom
    FROM tmp_acha_segment
) AS endpoint;

CREATE UNIQUE INDEX tmp_acha_endpoint_pk
    ON tmp_acha_endpoint (segment_id, endpoint_type);

CREATE UNIQUE INDEX tmp_acha_endpoint_id_uq
    ON tmp_acha_endpoint (endpoint_id);

CREATE INDEX tmp_acha_endpoint_geom_gix
    ON tmp_acha_endpoint
    USING gist (geom);

-- 서로 1m 이내인 끝점의 인접 관계를 만든 뒤 재귀 탐색으로 연결 군집을 구한다.
-- minpoints가 1인 DBSCAN과 같은 연결 결과를 내며 PostGIS 버전별 윈도 함수
-- 구문 차이에 의존하지 않는다.
CREATE TEMP TABLE tmp_acha_endpoint_clustered
ON COMMIT DROP
AS
WITH RECURSIVE adjacency AS (
    SELECT
        endpoint_a.endpoint_id AS from_endpoint_id,
        endpoint_b.endpoint_id AS to_endpoint_id
    FROM tmp_acha_endpoint AS endpoint_a
    JOIN tmp_acha_endpoint AS endpoint_b
      ON ST_DWithin(endpoint_a.geom, endpoint_b.geom, 1.0)
),
reachable AS (
    SELECT
        endpoint_id AS start_endpoint_id,
        endpoint_id AS reached_endpoint_id
    FROM tmp_acha_endpoint

    UNION

    SELECT
        reachable.start_endpoint_id,
        adjacency.to_endpoint_id
    FROM reachable
    JOIN adjacency
      ON adjacency.from_endpoint_id = reachable.reached_endpoint_id
),
cluster_membership AS (
    SELECT
        reached_endpoint_id AS endpoint_id,
        MIN(start_endpoint_id)::bigint AS cluster_no
    FROM reachable
    GROUP BY reached_endpoint_id
)
SELECT
    endpoint.segment_id,
    endpoint.raw_trail_id,
    endpoint.endpoint_type,
    endpoint.geom,
    membership.cluster_no
FROM tmp_acha_endpoint AS endpoint
JOIN cluster_membership AS membership
  ON membership.endpoint_id = endpoint.endpoint_id;

CREATE UNIQUE INDEX tmp_acha_endpoint_clustered_pk
    ON tmp_acha_endpoint_clustered (segment_id, endpoint_type);

CREATE INDEX tmp_acha_endpoint_clustered_cluster_idx
    ON tmp_acha_endpoint_clustered (cluster_no);

-- 각 군집에서 정렬상 첫 번째 끝점을 대표 노드 좌표로 사용한다.
-- 평균 좌표를 사용하지 않으므로 노드는 항상 실제 segment 끝점과 일치한다.
CREATE TEMP TABLE tmp_acha_node_candidate
ON COMMIT DROP
AS
SELECT DISTINCT ON (cluster_no)
    cluster_no,
    geom
FROM tmp_acha_endpoint_clustered
ORDER BY cluster_no, segment_id, endpoint_type;

CREATE UNIQUE INDEX tmp_acha_node_candidate_cluster_uq
    ON tmp_acha_node_candidate (cluster_no);

INSERT INTO public.trail_node (
    mountain_id,
    place_id,
    component_no,
    edge_cnt,
    geom
)
SELECT
    current_setting('orda.seed.mountain_id')::integer,
    NULL,
    NULL,
    0,
    candidate.geom
FROM tmp_acha_node_candidate AS candidate
ORDER BY candidate.cluster_no;

-- 자동 생성된 node_id를 끝점 군집 번호와 연결한다.
CREATE TEMP TABLE tmp_acha_node_map
ON COMMIT DROP
AS
SELECT
    candidate.cluster_no,
    node.node_id
FROM tmp_acha_node_candidate AS candidate
JOIN public.trail_node AS node
  ON node.mountain_id = current_setting('orda.seed.mountain_id')::integer
 AND ST_Equals(node.geom, candidate.geom);

CREATE UNIQUE INDEX tmp_acha_node_map_cluster_uq
    ON tmp_acha_node_map (cluster_no);

CREATE UNIQUE INDEX tmp_acha_node_map_node_uq
    ON tmp_acha_node_map (node_id);

-- 각 분할 segment의 시작 노드와 끝 노드를 결정한다.
CREATE TEMP TABLE tmp_acha_edge_node_map
ON COMMIT DROP
AS
SELECT
    source_endpoint.segment_id,
    source_endpoint.raw_trail_id,
    source_node.node_id AS source_node_id,
    target_node.node_id AS target_node_id
FROM tmp_acha_endpoint_clustered AS source_endpoint
JOIN tmp_acha_node_map AS source_node
  ON source_node.cluster_no = source_endpoint.cluster_no
JOIN tmp_acha_endpoint_clustered AS target_endpoint
  ON target_endpoint.segment_id = source_endpoint.segment_id
 AND target_endpoint.endpoint_type = 'TARGET'
JOIN tmp_acha_node_map AS target_node
  ON target_node.cluster_no = target_endpoint.cluster_no
WHERE source_endpoint.endpoint_type = 'SOURCE';

CREATE UNIQUE INDEX tmp_acha_edge_node_map_pk
    ON tmp_acha_edge_node_map (segment_id);

-- 분할 segment 하나당 edge 하나를 생성하며 원본 raw_trail_id를 보존한다.
INSERT INTO public.trail_edge (
    mountain_id,
    source_node_id,
    target_node_id,
    raw_trail_id,
    geom,
    length_m,
    fwd_uphill_yn,
    direction_basis_cd,
    fwd_time_min,
    rev_time_min,
    fwd_ascent_m,
    fwd_descent_m,
    stair_spot_cnt,
    pass_yn
)
SELECT
    segment.mountain_id,
    edge_node.source_node_id,
    edge_node.target_node_id,
    segment.raw_trail_id,
    segment.geom,
    ST_Length(segment.geom),
    NULL,
    'UNKNOWN',
    NULL,
    NULL,
    NULL,
    NULL,
    0,
    'Y'
FROM tmp_acha_segment AS segment
JOIN tmp_acha_edge_node_map AS edge_node
  ON edge_node.segment_id = segment.segment_id
ORDER BY segment.segment_id;

-- 각 노드에 접속한 edge 수를 계산한다. 자기 루프는 차수 2로 계산된다.
WITH incident_edge AS (
    SELECT source_node_id AS node_id
    FROM public.trail_edge
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer

    UNION ALL

    SELECT target_node_id AS node_id
    FROM public.trail_edge
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
),
edge_count AS (
    SELECT node_id, COUNT(*)::integer AS edge_cnt
    FROM incident_edge
    GROUP BY node_id
)
UPDATE public.trail_node AS node
SET edge_cnt = edge_count.edge_cnt
FROM edge_count
WHERE node.mountain_id = current_setting('orda.seed.mountain_id')::integer
  AND node.node_id = edge_count.node_id;

-- pgRouting으로 연결요소를 계산하고 1부터 연속된 component_no를 부여한다.
WITH connected AS (
    SELECT component, node
    FROM pgr_connectedComponents(
    	$edges$
        SELECT edge_id AS id,
                source_node_id AS source,
                target_node_id AS target,
                length_m::float8 AS cost
        FROM public.trail_edge
        WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
        $edges$
    )
),
ranked AS (
    SELECT
        node,
        DENSE_RANK() OVER (ORDER BY component)::integer AS component_no
    FROM connected
)
UPDATE public.trail_node AS trail_node
SET component_no = ranked.component_no
FROM ranked
WHERE trail_node.mountain_id = current_setting('orda.seed.mountain_id')::integer
  AND trail_node.node_id = ranked.node;

-- 생성 결과가 분할 segment와 일치하지 않으면 트랜잭션을 중단한다.
DO $$
DECLARE
    expected_edge_count bigint;
    actual_edge_count bigint;
    missing_node_metadata_count bigint;
BEGIN
    SELECT COUNT(*)
    INTO expected_edge_count
    FROM tmp_acha_segment;

    SELECT COUNT(*)
    INTO actual_edge_count
    FROM public.trail_edge
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;

    IF actual_edge_count <> expected_edge_count THEN
        RAISE EXCEPTION
            'trail_edge 건수 불일치: 예상 %, 실제 %',
            expected_edge_count,
            actual_edge_count;
    END IF;

    SELECT COUNT(*)
    INTO missing_node_metadata_count
    FROM public.trail_node
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
      AND (
          component_no IS NULL
          OR edge_cnt IS NULL
          OR edge_cnt = 0
      );

    IF missing_node_metadata_count > 0 THEN
        RAISE EXCEPTION
            'component_no 또는 edge_cnt가 계산되지 않은 노드가 %개 있습니다.',
            missing_node_metadata_count;
    END IF;
END
$$;

-- 생성된 네트워크에서 서비스 가능 영역을 만든다.
-- 아차산 서비스 가능 영역 생성
--
-- acha_seed.sql 실행 후 생성된 통행 가능 trail_edge를 기준으로 한다.
-- EPSG:5179의 거리 단위를 사용해 등산로 양쪽 200m를 서비스 가능 영역으로 잡고,
-- 버퍼 결합 과정에서 생긴 내부 구멍은 외곽 링만 다시 폴리곤으로 만들어 제거한다.
-- mountain_id와 dataset_id는 환경마다 달라질 수 있으므로 이름으로 조회한다.
-- 기존 아차산 service_area가 있으면 갱신하고, 없으면 새로 생성한다.


-- 산과 파생 데이터셋이 정확히 하나씩 존재하고 네트워크가 준비됐는지 확인한다.
DO $$
DECLARE
    mountain_count bigint;
    dataset_count bigint;
    edge_count bigint;
BEGIN
    SELECT COUNT(*)
    INTO mountain_count
    FROM public.mountain
    WHERE mountain_nm = '아차산'
      AND use_yn = 'Y';

    IF mountain_count <> 1 THEN
        RAISE EXCEPTION
            '사용 중인 아차산 데이터가 정확히 1건이어야 합니다. 실제: %건',
            mountain_count;
    END IF;

    SELECT COUNT(*)
    INTO dataset_count
    FROM public.source_dataset
    WHERE dataset_nm = 'derived:acha:service_area';

    IF dataset_count <> 1 THEN
        RAISE EXCEPTION
            '서비스 영역 데이터셋이 정확히 1건이어야 합니다. 실제: %건',
            dataset_count;
    END IF;

    SELECT COUNT(*)
    INTO edge_count
    FROM public.trail_edge AS edge
    JOIN public.mountain AS mountain
      ON mountain.mountain_id = edge.mountain_id
    WHERE mountain.mountain_nm = '아차산'
      AND mountain.use_yn = 'Y'
      AND edge.pass_yn = 'Y'
      AND edge.geom IS NOT NULL;

    IF edge_count = 0 THEN
        RAISE EXCEPTION
            '아차산 통행 가능 trail_edge가 없습니다. acha_seed.sql을 먼저 실행하세요.';
    END IF;
END
$$;

-- 서비스 영역 데이터셋 메타데이터를 현재 파생 규칙에 맞게 갱신한다.
-- 결과 형상은 현재 trail_edge에서 매번 계산되므로 고정 파일 해시는 사용하지 않는다.
UPDATE public.source_dataset
SET file_nm = 'acha_seed.sql',
    file_hash = NULL,
    data_ver = 'network-buffer-200m-v1',
    dataset_desc = '아차산 통행 가능 trail_edge에 200m 버퍼를 적용하고 내부 구멍을 제거한 서비스 가능 영역.'
WHERE dataset_nm = 'derived:acha:service_area';

WITH target_mountain AS (
    SELECT mountain_id
    FROM public.mountain
    WHERE mountain_nm = '아차산'
      AND use_yn = 'Y'
),
target_dataset AS (
    SELECT dataset_id
    FROM public.source_dataset
    WHERE dataset_nm = 'derived:acha:service_area'
),
buffered_area AS (
    SELECT
        mountain.mountain_id,
        ST_Union(ST_Buffer(edge.geom, 200.0)) AS geom
    FROM target_mountain AS mountain
    JOIN public.trail_edge AS edge
      ON edge.mountain_id = mountain.mountain_id
    WHERE edge.pass_yn = 'Y'
      AND edge.geom IS NOT NULL
    GROUP BY mountain.mountain_id
),
polygon_parts AS (
    SELECT
        area.mountain_id,
        (ST_Dump(ST_CollectionExtract(area.geom, 3))).geom AS geom
    FROM buffered_area AS area
),
filled_area AS (
    SELECT
        part.mountain_id,
        ST_Multi(
            ST_Union(
                ST_MakePolygon(ST_ExteriorRing(part.geom))
            )
        )::geometry(MultiPolygon, 5179) AS geom
    FROM polygon_parts AS part
    GROUP BY part.mountain_id
),
updated AS (
    UPDATE public.service_area AS service_area
    SET dataset_id = dataset.dataset_id,
        area_nm = '아차산 서비스 가능 영역',
        geom = area.geom,
        use_yn = 'Y'
    FROM filled_area AS area
    CROSS JOIN target_dataset AS dataset
    WHERE service_area.mountain_id = area.mountain_id
    RETURNING service_area.area_id
)
INSERT INTO public.service_area (
    mountain_id,
    dataset_id,
    area_nm,
    geom,
    use_yn
)
SELECT
    area.mountain_id,
    dataset.dataset_id,
    '아차산 서비스 가능 영역',
    area.geom,
    'Y'
FROM filled_area AS area
CROSS JOIN target_dataset AS dataset
WHERE NOT EXISTS (
    SELECT 1
    FROM updated
);

-- 생성 결과와 전체 통행 가능 edge 포함 여부를 검증한다.
DO $$
DECLARE
    service_area_count bigint;
    invalid_area_count bigint;
    outside_edge_count bigint;
BEGIN
    SELECT COUNT(*)
    INTO service_area_count
    FROM public.service_area AS service_area
    JOIN public.mountain AS mountain
      ON mountain.mountain_id = service_area.mountain_id
    WHERE mountain.mountain_nm = '아차산'
      AND mountain.use_yn = 'Y'
      AND service_area.use_yn = 'Y';

    IF service_area_count <> 1 THEN
        RAISE EXCEPTION
            '사용 중인 아차산 서비스 영역이 정확히 1건이어야 합니다. 실제: %건',
            service_area_count;
    END IF;

    SELECT COUNT(*)
    INTO invalid_area_count
    FROM public.service_area AS service_area
    JOIN public.mountain AS mountain
      ON mountain.mountain_id = service_area.mountain_id
    WHERE mountain.mountain_nm = '아차산'
      AND mountain.use_yn = 'Y'
      AND service_area.use_yn = 'Y'
      AND (
          service_area.geom IS NULL
          OR ST_IsEmpty(service_area.geom)
          OR NOT ST_IsValid(service_area.geom)
          OR ST_SRID(service_area.geom) <> 5179
          OR GeometryType(service_area.geom) <> 'MULTIPOLYGON'
      );

    IF invalid_area_count > 0 THEN
        RAISE EXCEPTION
            '아차산 서비스 영역의 형상 유형, SRID 또는 유효성이 올바르지 않습니다.';
    END IF;

    SELECT COUNT(*)
    INTO outside_edge_count
    FROM public.trail_edge AS edge
    JOIN public.mountain AS mountain
      ON mountain.mountain_id = edge.mountain_id
    WHERE mountain.mountain_nm = '아차산'
      AND mountain.use_yn = 'Y'
      AND edge.pass_yn = 'Y'
      AND edge.geom IS NOT NULL
      AND NOT EXISTS (
          SELECT 1
          FROM public.service_area AS service_area
          WHERE service_area.mountain_id = edge.mountain_id
            AND service_area.use_yn = 'Y'
            AND ST_Covers(service_area.geom, edge.geom)
      );

    IF outside_edge_count > 0 THEN
        RAISE EXCEPTION
            '서비스 영역에 포함되지 않은 아차산 trail_edge가 %건 있습니다.',
            outside_edge_count;
    END IF;
END
$$;
-- 상세지점 설명과 원천 분류에서 검증 가능한 키워드 태그를 생성한다.
WITH target_spot AS (
    SELECT
        spot_id,
        lower(concat_ws(' ', src_class_nm, detail_txt, etc_txt)) AS description
    FROM public.trail_spot
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
), extracted AS (
    SELECT spot_id, 'STAIR'::varchar(20) AS tag_cd FROM target_spot WHERE description ~ '계단'
    UNION SELECT spot_id, 'REST' FROM target_spot WHERE description ~ '벤치|쉼터|정자|평상'
    UNION SELECT spot_id, 'VIEW' FROM target_spot WHERE description ~ '조망|전망' AND description !~ '철조망'
    UNION SELECT spot_id, 'STEEP' FROM target_spot WHERE description ~ '깔딱|경사심함|직벽|바위오름'
    UNION SELECT spot_id, 'ROPE' FROM target_spot WHERE description ~ '로프|밧줄' AND description !~ '경계로프'
    UNION SELECT spot_id, 'DANGER' FROM target_spot WHERE description ~ '위험|낙석|붕괴|미끄러|빙판|절벽'
    UNION SELECT spot_id, 'WATER' FROM target_spot WHERE description ~ '약수|샘터|식수'
    UNION SELECT spot_id, 'PEAK' FROM target_spot WHERE description ~ '정상|정상부|봉우리'
    UNION SELECT spot_id, 'TOILET' FROM target_spot WHERE description ~ '화장실'
    UNION SELECT spot_id, 'PARKING' FROM target_spot WHERE description ~ '주차장'
    UNION SELECT spot_id, 'HELIPAD' FROM target_spot WHERE description ~ '헬기장'
)
INSERT INTO public.spot_tag (spot_id, tag_cd, extract_type_cd, verify_status_cd)
SELECT spot_id, tag_cd, 'KEYWORD', 'UNVERIFIED'
FROM extracted
ON CONFLICT (spot_id, tag_cd) DO NOTHING;


-- 상세지점을 가장 가까운 등산로 구간에 연결하고 계단 수를 반영한다.
-- 아차산 상세지점-등산로 구간 매칭 및 구간별 계단 지점 수

-- 대상 산: mountain_id = current_setting('orda.seed.mountain_id')::integer

-- 대상 좌표계: EPSG:5179


-- 이 파일 앞부분에서 생성한 네트워크와 상세지점을 사용한다.
-- trail_edge의 edge_id는 시퀀스 값이므로 이 파일은 edge_id를 고정하지 않고
-- 실행 시점의 geometry 로 가장 가까운 구간을 계산한다. 다시 실행해도 같은 행이 중복되지 않는다.
--
-- 매칭 원칙:
--   * 모든 상세지점을 가장 가까운 trail_edge 하나에 연결한다. 거리가 같으면 edge_id 가 작은 구간을 쓴다.
--   * 최대 거리 제한을 두지 않고 dist_m 에 실제 거리(m)를 저장한다. 먼 매칭의 불확실성은 dist_m 으로 판단한다.
--     적재 후 검증 쿼리에서 거리 분포와 최대 거리를 확인한다.
--   * pos_ratio 는 구간 geometry 시작점 기준 0~1 위치이다.
--   * 이미 매칭이 있는 지점(수동 보정 포함)은 건드리지 않는다.
--   * 검수 전이므로 match_type_cd, match_status_cd 는 AUTO 이다.

-- 같은 산의 네트워크 작업과 동시에 실행되지 않도록 같은 트랜잭션 잠금을 건다.
SELECT pg_advisory_xact_lock(5179, current_setting('orda.seed.mountain_id')::integer);

-- 선행 데이터가 없으면 아무것도 넣지 않고 중단한다.
DO $$
DECLARE
    edge_cnt bigint;
    spot_cnt bigint;
BEGIN
    SELECT count(*) INTO edge_cnt FROM public.trail_edge WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;
    SELECT count(*) INTO spot_cnt FROM public.trail_spot WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;
    IF edge_cnt = 0 OR spot_cnt = 0 THEN
        RAISE EXCEPTION '선행 시드 누락: trail_edge %, trail_spot %', edge_cnt, spot_cnt;
    END IF;
END
$$;

INSERT INTO public.spot_edge_match (
    spot_id, edge_id, raw_trail_id, dist_m, pos_ratio, match_type_cd, match_status_cd
)
SELECT
    spot.spot_id,
    nearest.edge_id,
    nearest.raw_trail_id,
    round(ST_Distance(spot.geom, nearest.geom)::numeric, 2),
    round(ST_LineLocatePoint(nearest.geom, spot.geom)::numeric, 6),
    'AUTO',
    'AUTO'
FROM public.trail_spot AS spot
CROSS JOIN LATERAL (
    SELECT edge.edge_id, edge.raw_trail_id, edge.geom
    FROM public.trail_edge AS edge
    WHERE edge.mountain_id = spot.mountain_id
    ORDER BY ST_Distance(spot.geom, edge.geom), edge.edge_id
    LIMIT 1
) AS nearest
WHERE spot.mountain_id = current_setting('orda.seed.mountain_id')::integer
  AND NOT EXISTS (
      SELECT 1
      FROM public.spot_edge_match AS existing
      WHERE existing.spot_id = spot.spot_id
  )
ON CONFLICT (spot_id, edge_id)
DO NOTHING;

-- 구간별 계단 지점 수 (trail_edge.stair_spot_cnt)
--   * 대상: STAIR 태그가 REJECTED 가 아니고 매칭이 REJECTED 가 아닌 지점
--   * 같은 계단이 여러 점으로 찍힌 경우를 한 번만 센다.
--     - '계단시작'·'계단끝' 표시 지점은 같은 구간에서 짝을 지어 max(시작 수, 끝 수)로 센다.
--     - 그 밖의 계단 지점은 같은 구간 안에서 10m 이내로 붙어 있으면 하나로 센다.
--   * 한 계단이 구간 경계를 넘으면 걸친 구간마다 1로 센다.
--   * 매번 전체를 다시 계산하므로, 값이 달라진 구간만 갱신한다. 그 밖의 trail_edge 컬럼은 바꾸지 않는다.
WITH stair_spot AS (
    SELECT
        match.edge_id,
        spot.geom,
        CASE
            WHEN spot.detail_txt ~ '계단시작' THEN 'START'
            WHEN spot.detail_txt ~ '계단끝' THEN 'END'
            ELSE 'POINT'
        END AS stair_kind
    FROM public.spot_edge_match AS match
    JOIN public.trail_spot AS spot ON spot.spot_id = match.spot_id
    JOIN public.spot_tag AS tag ON tag.spot_id = spot.spot_id
    WHERE spot.mountain_id = current_setting('orda.seed.mountain_id')::integer
      AND match.match_status_cd <> 'REJECTED'
      AND tag.tag_cd = 'STAIR'
      AND tag.verify_status_cd <> 'REJECTED'
),
point_cluster AS (
    SELECT
        edge_id,
        ST_ClusterDBSCAN(geom, eps := 10, minpoints := 1) OVER (PARTITION BY edge_id) AS cluster_no
    FROM stair_spot
    WHERE stair_kind = 'POINT'
),
edge_stair AS (
    SELECT edge_id, count(DISTINCT cluster_no) AS stair_cnt
    FROM point_cluster
    GROUP BY edge_id
    UNION ALL
    SELECT
        edge_id,
        greatest(count(*) FILTER (WHERE stair_kind = 'START'), count(*) FILTER (WHERE stair_kind = 'END'))
    FROM stair_spot
    WHERE stair_kind <> 'POINT'
    GROUP BY edge_id
),
edge_total AS (
    SELECT edge.edge_id, coalesce(sum(edge_stair.stair_cnt), 0)::integer AS stair_cnt
    FROM public.trail_edge AS edge
    LEFT JOIN edge_stair ON edge_stair.edge_id = edge.edge_id
    WHERE edge.mountain_id = current_setting('orda.seed.mountain_id')::integer
    GROUP BY edge.edge_id
)
UPDATE public.trail_edge AS edge
SET stair_spot_cnt = edge_total.stair_cnt
FROM edge_total
WHERE edge.edge_id = edge_total.edge_id
  AND edge.stair_spot_cnt IS DISTINCT FROM edge_total.stair_cnt;

-- 매칭되지 않은 상세지점이 있으면 조용히 넘어가지 않도록 실패시킨다.
DO $$
DECLARE
    unmatched_cnt bigint;
BEGIN
    SELECT count(*) INTO unmatched_cnt
    FROM public.trail_spot AS spot
    WHERE spot.mountain_id = current_setting('orda.seed.mountain_id')::integer
      AND NOT EXISTS (
          SELECT 1 FROM public.spot_edge_match AS match WHERE match.spot_id = spot.spot_id
      );
    IF unmatched_cnt > 0 THEN
        RAISE EXCEPTION '구간에 매칭되지 않은 상세지점 %건', unmatched_cnt;
    END IF;
END
$$;
-- 최종 데이터와 공간 형상을 검증한다.
DO $$
DECLARE
    invalid_raw bigint;
    invalid_spot bigint;
    edge_count bigint;
    node_count bigint;
BEGIN
    SELECT COUNT(*) INTO invalid_raw
    FROM public.raw_trail
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
      AND (geom IS NULL OR ST_IsEmpty(geom) OR NOT ST_IsValid(geom)
           OR ST_SRID(geom) <> 5179 OR GeometryType(geom) <> 'LINESTRING');

    SELECT COUNT(*) INTO invalid_spot
    FROM public.trail_spot
    WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer
      AND (geom IS NULL OR ST_IsEmpty(geom) OR NOT ST_IsValid(geom)
           OR ST_SRID(geom) <> 5179 OR GeometryType(geom) <> 'POINT');

    SELECT COUNT(*) INTO edge_count FROM public.trail_edge WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;
    SELECT COUNT(*) INTO node_count FROM public.trail_node WHERE mountain_id = current_setting('orda.seed.mountain_id')::integer;

    IF invalid_raw <> 0 OR invalid_spot <> 0 THEN
        RAISE EXCEPTION '아차산 공간 형상 검증 실패(raw %, spot %).', invalid_raw, invalid_spot;
    END IF;
    IF edge_count = 0 OR node_count = 0 THEN
        RAISE EXCEPTION '아차산 네트워크 생성 실패(edge %, node %).', edge_count, node_count;
    END IF;
END
$$;

COMMIT;
